import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [count, setCount] = useState(0);
  // энд бичнэ үү: add-г useCallback-аар тогтворжуул
  const add = () => setCount((c) => c + 1);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.c}>Сагс: {count}</Text>
      <Pressable nativeID="add" style={styles.b} onPress={add}><Text style={styles.t}>Нэмэх</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, padding: 24, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 24, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState, useCallback } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [count, setCount] = useState(0);
  const add = useCallback(() => setCount((c) => c + 1), []);
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.c}>Сагс: {count}</Text>
      <Pressable nativeID="add" style={styles.b} onPress={add}><Text style={styles.t}>Нэмэх</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, padding: 24, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 24, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
